//! Generated by steelix from `python -m store` and the modules of its project.

#![allow(non_snake_case, unused_variables, unused_assignments)]
#![allow(clippy::never_loop, clippy::approx_constant, clippy::if_same_then_else)]
#![allow(clippy::too_many_arguments, clippy::doc_lazy_continuation)]

mod config;
mod store;

use steelix_runtime::NativeModule;

/// The project's modules: `import` runs their transpiled code instead of
/// their Python source.
const MODULES: &[NativeModule] = &[
    NativeModule::module("config", config::exec_module),
    NativeModule::package("store", store::exec_module),
    NativeModule::module("store.__main__", store::__main__::exec_module),
    NativeModule::module("store.audit", store::audit::exec_module),
    NativeModule::module("store.errors", store::errors::exec_module),
    NativeModule::module("store.inventory", store::inventory::exec_module),
    NativeModule::module("store.items", store::items::exec_module),
    NativeModule::package("store.reports", store::reports::exec_module),
    NativeModule::module("store.reports.text", store::reports::text::exec_module),
];

fn main() -> std::process::ExitCode {
    let script = steelix_runtime::embed::Script {
        argv0: "$ROOT/tests/projects/inventory/store/__main__.py",
        file: "$ROOT/tests/projects/inventory/store/__main__.py",
        dir: "$ROOT/tests/projects/inventory",
    };
    steelix_runtime::embed::run_module(env!("STEELIX_PYTHON"), &script, MODULES, "store.__main__")
}
